//! Cross-implementation mixer lock: replays the golden event stream from
//! `shared/contracts/fixtures/audio/mixer-golden.bin` through the
//! battuta-audio mixer and requires bit-identical output. The C# side
//! replays the same stream through the Windows `PolyphonicSampleProvider`
//! (`Battuta.Windows.Tests/Audio/MixerGoldenFixtureTests`), which locks the
//! two implementations together.
//!
//! The fixture is generated by `src/bin/golden_gen.rs` and committed; the
//! test never regenerates it.

use battuta_audio::OUTPUT_CHANNELS;
use battuta_audio::bank::SampleBank;
use battuta_audio::engine::AudioEngine;
use battuta_audio::mixer::Mixer;
use battuta_audio::ring::SpscCommandRing;
use battuta_audio::stats::AudioStats;

struct Reader<'a> {
    bytes: &'a [u8],
    offset: usize,
}

impl<'a> Reader<'a> {
    fn new(bytes: &'a [u8]) -> Self {
        Self { bytes, offset: 0 }
    }

    fn take(&mut self, count: usize) -> &'a [u8] {
        let slice = &self.bytes[self.offset..self.offset + count];
        self.offset += count;
        slice
    }

    fn u32(&mut self) -> u32 {
        u32::from_le_bytes(self.take(4).try_into().unwrap())
    }

    fn f32(&mut self) -> f32 {
        f32::from_le_bytes(self.take(4).try_into().unwrap())
    }

    fn u8(&mut self) -> u8 {
        self.take(1)[0]
    }
}

#[test]
fn mixer_renders_the_golden_transcript_bit_exact() {
    let path = fixture_path();
    let bytes = std::fs::read(&path)
        .unwrap_or_else(|error| panic!("read fixture {}: {error}", path.display()));
    let mut reader = Reader::new(&bytes);

    assert_eq!(reader.take(4), b"BTAU", "fixture magic");
    assert_eq!(reader.u32(), 1, "fixture version");

    let sample_count = reader.u32() as usize;
    let mut samples: Vec<(u32, Vec<f32>)> = Vec::with_capacity(sample_count);
    for _ in 0..sample_count {
        let handle = reader.u32();
        let frame_count = reader.u32() as usize;
        let data = (0..frame_count).map(|_| reader.f32()).collect();
        samples.push((handle, data));
    }

    let chunk_frames = reader.u32() as usize;
    let event_count = reader.u32() as usize;

    let ring = SpscCommandRing::new();
    let bank = SampleBank::new();
    let mixer = Mixer::new();
    let stats = AudioStats::default();
    let mut chunk = vec![0.0_f32; chunk_frames * OUTPUT_CHANNELS];

    // The engine object is not used directly here (the test drives ring,
    // bank, and mixer exactly like the PipeWire process callback will), but
    // constructing it keeps the default set honest.
    let _engine = AudioEngine::new();

    for (handle, data) in &samples {
        let registered = bank
            .register(data.clone())
            .unwrap_or_else(|| panic!("register sample {handle}"));
        assert_eq!(registered, *handle, "fixture handles map to bank slots");
    }

    let mut events_seen = 0;
    let mut output = Vec::new();
    while events_seen < event_count {
        match reader.u8() {
            0 => {
                let sample = reader.u32();
                let gain = reader.f32();
                let rate = reader.f32();
                let allows_stealing = reader.u8() != 0;
                mixer.try_schedule(&ring, &bank, &stats, sample, gain, rate, allows_stealing);
            }
            1 => {
                // SAFETY: this test is the single render thread here.
                unsafe { mixer.render(&ring, &bank, &stats, &mut chunk) };
                output.extend_from_slice(&chunk);
            }
            other => panic!("unknown event kind {other}"),
        }
        events_seen += 1;
    }

    // The transcript must have exercised steals and drops (generator sanity).
    assert!(stats.voice_steals() > 0, "transcript must exercise steals");
    assert!(
        stats.dropped_commands() > 0,
        "transcript must exercise drops"
    );

    let expected: Vec<f32> = {
        let remaining = reader.bytes.len() - reader.offset;
        assert_eq!(remaining % 4, 0, "expected output is f32-aligned");
        (0..remaining / 4).map(|_| reader.f32()).collect()
    };
    assert_eq!(reader.offset, reader.bytes.len(), "fixture fully consumed");
    assert_eq!(
        output.len(),
        expected.len(),
        "rendered frame count must match the fixture"
    );
    for (index, (actual, expected)) in output.iter().zip(expected.iter()).enumerate() {
        assert_eq!(
            actual.to_bits(),
            expected.to_bits(),
            "output sample {index} differs (voice mixing must be bit-exact)"
        );
    }
}

fn fixture_path() -> std::path::PathBuf {
    let manifest = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let mut directory = manifest.parent();
    while let Some(parent) = directory {
        if parent.join("shared/contracts").is_dir() {
            return parent.join("shared/contracts/fixtures/audio/mixer-golden.bin");
        }
        directory = parent.parent();
    }
    panic!("could not locate the repository root from {manifest:?}");
}
